fn is_nested(s: Vec<i8>) -> bool {
    // We need at least four elements to match 0,0,1,1 in order.
    if s.len() < 4 {
        return false;
    }

    // Greedily find two 0's, then two 1's in the remaining part of the sequence.
    let mut zeros_found = 0;
    let mut ones_found = 0;

    for &x in &s {
        // First, collect up to two zeros.
        if zeros_found < 2 {
            if x == 0 {
                zeros_found += 1;
            }
        } else {
            // Once we have two zeros, collect up to two ones.
            if x == 1 {
                ones_found += 1;
                if ones_found == 2 {
                    return true;
                }
            }
        }
    }

    // If we never saw two 1's after two 0's, return false.
    false
}

